import{_ as e,o as t,c as n,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"Ceph Practice and Usage in China Mobile - Zhang Shaowen, China Mobile (Suzhou) Software Technology","description":"","frontmatter":{"title":"Ceph Practice and Usage in China Mobile - Zhang Shaowen, China Mobile (Suzhou) Software Technology","date":"2019-05-24T00:00:00.000Z","updated":"2019-05-24T00:00:00.000Z","tags":["Ceph","Distributed Storage","Cloud Computing","China Mobile","Object Storage"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/Ceph_Practice_And_Usage_In_China_Mobile_-_Zhang_Shaowen_China_Mobile_Suzhou_Software_Technology.md","filePath":"posts/2019/Ceph_Practice_And_Usage_In_China_Mobile_-_Zhang_Shaowen_China_Mobile_Suzhou_Software_Technology.md","lastUpdated":1780459816000}'),a={name:"posts/2019/Ceph_Practice_And_Usage_In_China_Mobile_-_Zhang_Shaowen_China_Mobile_Suzhou_Software_Technology.md"};function l(r,o,_,p,h,s){return t(),n("div",null,[...o[0]||(o[0]=[i("<p>中国移动（Suzhou）软件技术的张晓文在会议中分享了Ceph在中国移动实践与应用的情况。以下是会议的主要内容：</p><p><strong>一、中国移动业务介绍</strong></p><p>Carolyn介绍了中国移动的业务范围，强调其作为全球最大的移动通信运营商的重要性。</p><p><strong>二、中国Beryl云计算产品</strong></p><ol><li><strong>Cloud Recorder</strong>： 为Habana云性能管理提供支持。</li><li><strong>Big Cloud</strong>： 为超过30家中国移动专业公司提供IT服务。</li></ol><p><strong>三、中国Beryl云存储解决方案</strong></p><ol><li><strong>Block Storage</strong>： 使用Ceph块存储解决方案，总容量超过40PB，用于统一外交服务平台。</li><li><strong>Object Storage</strong>： 使用Ceph对象存储，总容量超过1300PB。</li></ol><p><strong>四、中国Beryl私有云</strong></p><ol><li><strong>一级私有云</strong>： 使用OpenStack平台，通过私有云管理平台实现资源统一管理。</li><li><strong>二级私有云</strong>： 总容量30PB，OSD数量超过2600个。</li></ol><p><strong>五、Ceph实践</strong></p><ol><li><strong>CephFS</strong>： 在CephFS基础上构建统一外交服务平台。</li><li><strong>Ceph Object Storage</strong>： 支持Swift和S3接口。</li><li><strong>Ceph管理平台</strong>： 用于集群部署、资源监控、自动化部署和运维升级等功能。</li><li><strong>Ceph硬件配置</strong>： 提供多种硬件配置，满足不同用户需求。</li><li><strong>Ceph缓存</strong>： 使用Ceph缓存技术提高数据访问效率。</li></ol><p><strong>六、Ceph Object Storage应用场景</strong></p><ol><li>备份虚拟机镜像。</li><li>存储图片、视频等大数据。</li><li>支持大数据系统，如Hadoop、Spark等。</li><li>托管企业网站、数据网站等。</li></ol><p><strong>七、后续行动计划</strong></p><ol><li>持续优化Ceph管理平台。</li><li>探索Ceph在更多领域的应用。</li><li>加强Ceph社区贡献。</li></ol><p>会议中提及的Ceph相关关键词包括：CephFS、Ceph Object Storage、Ceph Block Device、Ceph缓存、Ceph管理平台、Ceph硬件配置、Ceph缓存技术、Object Storage、Block Storage、Swift、S3等。</p>",16)])])}const c=e(a,[["render",l]]);export{C as __pageData,c as default};
